for (const it of all) seen.set(it.number, it);
const oct = [...seen.values()].filter((it) => {
  const t = it.closed_at;
  if (!t) return false;
  const d = new Date(t);
  return d.getUTCFullYear() === 2026 && d.getUTCMonth() === 9;
});
return {
  totalClosedFetched: seen.size,
  pages: page,
  shape,
  octoberCount: oct.length,
  sample: all.slice(0, 2).map((i) => ({ number: i.number, state: i.state, closed_at: i.closed_at, created_at: i.created_at })),
  missingClosedAt: [...seen.values()].filter((it) => !it.closed_at).length,
};
