const repo = "acme/cli";
const seen = new Map<number, any>();
let page: number | null = 1;
const pageLog: any[] = [];
let guard = 0;
while (page !== null && guard < 100) {
  guard++;
  const res: any = await tools.list_issues({ repo, state: "closed", page });
  const items: any[] = res?.items ?? [];
  pageLog.push({ page, count: items.length, next_page: res?.next_page ?? null });
  for (const it of items) seen.set(it.number, it);
  if (items.length === 0) break;
  page = res?.next_page ?? null;
}
const oct = [...seen.values()].filter((it) => {
  if (!it.closed_at) return false;
  const d = new Date(it.closed_at);
  return d.getUTCFullYear() === 2026 && d.getUTCMonth() === 9;
});
return {
  pageLog,
  totalClosed: seen.size,
  octoberCount: oct.length,
  octoberNumbers: oct.map((i) => i.number).sort((a, b) => a - b),
};
